  const row={email:'a\rb\nc',updated_at:'2026-10-01T00:00:00Z',name:'A, "B"',contact_id:'plain-rn'};
  assert.equal(toCsv([row]),'contact_id,name,email,updated_at\nplain-rn,"A, ""B""","a\rb\nc",2026-10-01T00:00:00Z\n');
});

